const current = $input.first().json;
const context = current.context || {};
const payload = current.payload || {};
const planCandidate = payload.plan || current.plan || {};
const lineDecisions =
  payload.line_decisions ||
  payload.plan?.line_decisions ||
  current.line_decisions ||
  current.plan?.line_decisions ||
  [];

function affectedLinesFromOperations(operations) {
  const seen = new Set();
  for (const operation of operations || []) {
    const path = operation.path || '';
    const parts = path.split('/').filter(Boolean);
    const lineIndex = parts.indexOf('lines');
    if (lineIndex >= 0 && parts[lineIndex + 1]) {
      seen.add(parts[lineIndex + 1]);
    }
  }
  return Array.from(seen).sort();
}

const candidatePatch =
  payload.candidate_patch ||
  payload.candidate_patch_summary ||
  current.candidate_patch ||
  current.body?.candidate_patch ||
  {};
function firstAffectedLines(...values) {
  for (const value of values) {
    if (Array.isArray(value) && value.length) return value;
  }
  return [];
}
const affectedLines = firstAffectedLines(
  context.affected_lines,
  payload.affected_lines,
  current.affected_lines,
  candidatePatch.affected_lines,
  affectedLinesFromOperations(candidatePatch.operations)
);

const normalizedPlan = {
  ...planCandidate,
  line_decisions: lineDecisions
};

const normalizedContext = {
  ...context,
  trt_id: context.trt_id || normalizedPlan.trt_id || null,
  trt_version: context.trt_version || normalizedPlan.trt_version || null,
  reconciliation_plan_id: context.reconciliation_plan_id || normalizedPlan.plan_id || null,
  affected_lines: affectedLines
};

const onlyNoChange = lineDecisions.length > 0 && lineDecisions.every(item => item.decision === 'NO_CHANGE');
const allowBaseline = current.allow_baseline_on_no_change === true || current.body?.allow_baseline_on_no_change === true || context.allow_baseline_on_no_change === true;
const evaluatesReleasedPatchImpact = affectedLines.length > 0;

if (onlyNoChange && !allowBaseline && !evaluatesReleasedPatchImpact) {
  return [{
    json: {
      status: 'NO_EFFECT',
      reason: 'Reconciliation plan contains no changed lines.',
      context: normalizedContext,
      payload: { ...payload, plan: normalizedPlan, affected_lines: affectedLines },
      errors: []
    }
  }];
}

return [{
  json: {
    status: 'READY_FOR_SCENARIO_GENERATION',
    context: normalizedContext,
    payload: { ...payload, plan: normalizedPlan, affected_lines: affectedLines },
    errors: []
  }
}];

const input = $input.first().json;
const context = input.context || {};
const payload = input.payload || {};
const plan = payload.plan || {};
function firstAffectedLines(...values) {
  for (const value of values) {
    if (Array.isArray(value) && value.length) return value;
  }
  for (const value of values) {
    if (Array.isArray(value)) return value;
  }
  return [];
}
const affectedLines = firstAffectedLines(
  context.affected_lines,
  payload.affected_lines,
  input.affected_lines
);
const lineDecisions = payload.line_decisions || payload.plan?.line_decisions || [];
const simulationScope = context.simulation_scope || payload.simulation_scope || input.simulation_scope || null;
const baseSimulationConfigUpdates = context.simulation_config_updates || payload.simulation_config_updates || input.simulation_config_updates || null;
const simulationConfigUpdates = (context.dry_run_only || payload.dry_run_only)
  ? { ...(baseSimulationConfigUpdates || {}), dry_run_only: true }
  : baseSimulationConfigUpdates;
const missing = [];

for (const field of ['release_id', 'trt_id', 'trt_version', 'reconciliation_plan_id']) {
  if (!context[field]) missing.push(field);
}

if (missing.length) {
  const message = `Missing ScenarioSpec generation fields: ${missing.join(', ')}`;
  return [{
    json: {
      status: 'REJECTED',
      context,
      ids: {
        release_id: context.release_id || null,
        audit_id: context.audit_id || null,
        trt_id: context.trt_id || null,
        trt_version: context.trt_version || null,
        reconciliation_plan_id: context.reconciliation_plan_id || null,
        scenario_spec_id: null
      },
      payload: {
        ...payload,
        plan,
        affected_lines: affectedLines,
        line_decisions: lineDecisions,
        message,
        missing_fields: missing
      },
      errors: [message]
    }
  }];
}

return [{
  json: {
    ...input,
    status: 'READY_FOR_SCENARIO_GENERATION',
    context,
    payload: {
      ...payload,
      plan,
      affected_lines: affectedLines,
      simulation_scope: simulationScope,
      simulation_config_updates: simulationConfigUpdates,
      line_decisions: lineDecisions
    },
    scenario_request: {
      release_id: context.release_id,
      trt_id: context.trt_id,
      trt_version: context.trt_version,
      reconciliation_plan_id: context.reconciliation_plan_id,
      candidate_strategy_id: 'primary',
      scenario_template_id: context.scenario_template_id || payload.scenario_template_id || null,
      include_waiting_scenarios: false,
      affected_lines: affectedLines,
      simulation_scope: simulationScope,
      simulation_config_updates: simulationConfigUpdates,
      line_decisions: lineDecisions
    },
    errors: []
  }
}];

const input = $input.first().json;
const message = (input.errors || [])[0] || 'Missing ScenarioSpec generation fields.';
return [{
  json: {
    status: 'REJECTED',
    context: input.context || {},
    ids: input.ids || {
      release_id: input.context?.release_id || null,
      audit_id: input.context?.audit_id || null,
      trt_id: input.context?.trt_id || null,
      trt_version: input.context?.trt_version || null,
      reconciliation_plan_id: input.context?.reconciliation_plan_id || null,
      scenario_spec_id: null
    },
    payload: input.payload || { message },
    errors: [message]
  }
}];

const input = $input.first().json;
const evidence = input.evidence_summary || input.payload?.evidence_summary || {};
const failedChecks = Array.isArray(input.failed_checks)
  ? input.failed_checks
  : (Array.isArray(evidence.failed_checks) ? evidence.failed_checks : []);
const failedLines = Array.isArray(input.failed_lines)
  ? input.failed_lines
  : (Array.isArray(evidence.failed_lines) ? evidence.failed_lines : []);
const operatorSummary =
  evidence.operator_detail_summary ||
  evidence.operator_summary ||
  input.payload?.message ||
  input.summary_message ||
  'Evidence summary was generated, but no operator summary was provided.';

const userMessageParts = [operatorSummary];
const options = Array.isArray(evidence.operator_options) ? evidence.operator_options : [];
const operatorExplanations = failedChecks.map(check => check.operator_explanation || check.operator_label || check.check_id).filter(Boolean);
const dryRunOnly = evidence.dry_run_only === true || evidence.simulation_config?.dry_run_only === true;
const asksDeploymentDecision = !dryRunOnly && (evidence.deployment_recommended === true || evidence.deployment_allowed === true);

if (dryRunOnly) {
  if (!operatorSummary.includes('No deployment is required')) {
    userMessageParts.push('');
    userMessageParts.push('No deployment is required for this dry run. Reply RERUN_SIMULATION to run it again, REQUEST_REVISION to adjust the request, or CANCEL to end.');
  }
} else if (evidence.deployment_recommended === true) {
  userMessageParts.push('');
  userMessageParts.push('Do you want to deploy this strategy to the simulated physical production line?');
  userMessageParts.push('Reply DEPLOY, DO_NOT_DEPLOY, or REQUEST_REVISION.');
} else if (evidence.deployment_allowed === true && evidence.requires_operator_acknowledgement === true) {
  userMessageParts.push('');
  userMessageParts.push('Deployment is allowed with operator acknowledgement, but it is not automatically recommended.');
  userMessageParts.push('Reply DEPLOY_WITH_ACK to deploy anyway, DO_NOT_DEPLOY to stop, REQUEST_REVISION to revise the strategy, or RERUN_SIMULATION to rerun the same ScenarioSpec.');
} else {
  userMessageParts.push('');
  userMessageParts.push('Deployment is not allowed for this evidence. Reply REQUEST_REVISION to revise the request, or RERUN_SIMULATION to rerun the same ScenarioSpec.');
}

const userMessage = userMessageParts.join('\n');
const deploymentQuestion = asksDeploymentDecision
  ? (evidence.requires_operator_acknowledgement === true
      ? 'Reply DEPLOY_WITH_ACK to deploy anyway, DO_NOT_DEPLOY, REQUEST_REVISION, or RERUN_SIMULATION.'
      : 'Do you want to deploy this to the simulated physical production line? Reply DEPLOY, DO_NOT_DEPLOY, or REQUEST_REVISION.')
  : null;
const nextStatus = asksDeploymentDecision ? 'WAITING_FOR_DEPLOYMENT_DECISION' : (dryRunOnly ? 'WAITING_FOR_POST_EVIDENCE_DECISION' : (input.status || evidence.status || 'EVIDENCE_READY'));

const base = {
  status: nextStatus,
  payload: {
    ...(input.payload || {}),
    evidence_summary: evidence,
    raw_evidence: input.raw_evidence,
    failed_checks: failedChecks,
    failed_lines: failedLines,
    line_results: input.line_results || evidence.line_results || [],
    operator_options: options,
    operator_explanations: operatorExplanations,
    acknowledged_risks: evidence.acknowledged_risks || [],
    dry_run_only: dryRunOnly,
    user_message: userMessage,
    message: userMessage,
    deployment_question: deploymentQuestion
  },
  errors: input.errors || []
};

try {
  const previous = $('Return Simulation Run Result').first().json;
  base.context = { ...(previous.context || {}), dry_run_only: dryRunOnly };
  base.ids = { ...(previous.ids || {}), run_id: input.run_id, scenario_spec_id: input.scenario_spec_id };
  base.payload = { ...(previous.payload || {}), ...base.payload };
} catch (error) {
  base.context = { ...(input.context || {}), dry_run_only: dryRunOnly };
}

return [{ json: base }];
